#include <vector>
#include <unordered_map>
using namespace std;

class Solution {
public:
    int countAlternatingXorPartitions(vector<int>& nums, int x1, int x2) {
        const int MOD = 1000000007;
        unordered_map<int, int> dp1_map, dp2_map;
        dp2_map[0] = 1;
        dp1_map[0] = 1;
        int pref = 0;
        int cur_ways1 = 0, cur_ways2 = 0;
        for (int x : nums) {
            pref ^= x;
            cur_ways1 = dp2_map[pref ^ x1] % MOD;
            cur_ways2 = dp1_map[pref ^ x2] % MOD;
            dp1_map[pref] = (dp1_map[pref] + cur_ways1) % MOD;
            dp2_map[pref] = (dp2_map[pref] + cur_ways2) % MOD;
        }
        if (x1 == x2) return cur_ways1;
        return (cur_ways1 + cur_ways2) % MOD;
    }
};

import java.util.*;

class Solution {
    public int countAlternatingXorPartitions(int[] nums, int x1, int x2) {
        final int MOD = 1_000_000_007;
        Map<Integer, Integer> dp1 = new HashMap<>();
        Map<Integer, Integer> dp2 = new HashMap<>();
        dp2.put(0, 1);
        dp1.put(0, 1);
        int pref = 0;
        int ways1 = 0, ways2 = 0;
        for (int x : nums) {
            pref ^= x;
            ways1 = dp2.getOrDefault(pref ^ x1, 0) % MOD;
            ways2 = dp1.getOrDefault(pref ^ x2, 0) % MOD;
            dp1.put(pref, (dp1.getOrDefault(pref, 0) + ways1) % MOD);
            dp2.put(pref, (dp2.getOrDefault(pref, 0) + ways2) % MOD);
        }
        if (x1 == x2) return ways1;
        return (ways1 + ways2) % MOD;
    }
}

var countAlternatingXorPartitions = function(nums, x1, x2) {
    const MOD = 1000000007;
    const dp1 = new Map([[0, 1]]);
    const dp2 = new Map([[0, 1]]);
    let pref = 0;
    let ways1 = 0, ways2 = 0;
    for (const x of nums) {
        pref ^= x;
        ways1 = (dp2.get(pref ^ x1) || 0) % MOD;
        ways2 = (dp1.get(pref ^ x2) || 0) % MOD;
        dp1.set(pref, ((dp1.get(pref) || 0) + ways1) % MOD);
        dp2.set(pref, ((dp2.get(pref) || 0) + ways2) % MOD);
    }
    if (x1 === x2) return ways1;
    return (ways1 + ways2) % MOD;
};
